import React from "react";
import Navbar from "./Navbar";
import "./IncomeCategory.css";

function IncomeCategory({ onNext }) {
  return (
    <>
      <Navbar title="Income Category" />

      <div className="income-container">
        <h1>Select Your Income Category</h1>

        <div className="income-grid">
          <div onClick={() => onNext("Fixed Income")} className="income-card">💼 Fixed</div>
          <div onClick={() => onNext("Freelancer")} className="income-card">🧑‍💻 Freelancer</div>
          <div onClick={() => onNext("Business")} className="income-card">🏢 Business</div>
          <div onClick={() => onNext("Multiple")} className="income-card">🔀 Multiple</div>
        </div>
      </div>
    </>
  );
}

export default IncomeCategory;
